            <div class="simple_top_shadow" v-if="cardStyle == 'simple'"></div>
            <div class="border cover" v-if="cardStyle != 'simple'"></div>
            <div class="simple_border cover" v-if="cardStyle == 'simple'"></div>
        </div>


        
