            <div class="simple_top_shadow" v-if="cardStyle == 'simple'"></div>
            <div class="name_tape" v-if="cardStyle != 'simple'"></div>
            <div class="bottom_tape">
                <div class="top_tape"></div>
            </div>
            <div class="border cover"></div>
        </div>
        <div class="card_border_style_red" v-if="warriorData.cardBorderIdx == 2">
