            <img src="../../assets/ui/ui2.webp" class="icon_img" v-if="warriorData.proficiency.achiv >= $store.profLevelList[1] && warriorData.proficiency.achiv < $store.profLevelList[2]"alt="" >
            <img src="../../assets/ui/ui3.webp" class="icon_img" v-if="warriorData.proficiency.achiv >= $store.profLevelList[2] && warriorData.proficiency.achiv < $store.profLevelList[3]"alt="" >
