            <img src="../../assets/ui/ui5.webp" class="icon_img" v-if="warriorData.proficiency.achiv >= $store.profLevelList[4]" alt="" >
        </div>
        
        
        <!-- <img src="../../assets/ui/ui (199).png" class="style_warrior_card_black_tape" alt=""> -->
