<script>
export default {
    name : 'WarriorCard',
    props: {
        warriorData: null,
        cardStyle: {
            default : "2_3",
            validator(value) {
                return ["2_3", "2_3_sml_pic","simple"].includes(value);
            }
        },
        filterGray:{
            type:Boolean,
            default : false,
        },
        showUpArms:{
            type:Boolean,
            default : false,
        }
    },
    computed:{
        //高级兵种图标
        UpArmsIconImg(){
            return require(`../../assets/${this.warriorData.isUpArms?"up_arms":"arms"}/${this.$store.armsMap[this.warriorData.upArms[this.warriorData.choseUpArmsIdx]]}.png`)
        },
    },
    mounted(){
    }
}
</script>

