<template>
    <div class="team">
        <div :class="'team_container '+ ($store.teams.list.length > 5 ? 'longer' : '')" ref="team_container">
            <div class="team_box" v-for="(t,tId) in $store.teams.list" :key="t.index">
                <!-- 武将卡 -->
                <div class="team_warrior" v-for="(w,wId) in $store.teams.list[tId]" :key="w.index" 
                >
                    <div class="cover" v-if="w.id != -1 && w.own" @click="WarriorInfoCheck(w,wId,tId)">
                        <WarriorElongatedCard :warriorData="w" cardStyle="2_1" :showUpArms="true" />
                        <div class="position_sign">
                            <span v-if="wId == 0">大营</span>
                            <span v-if="wId == 1">中军</span>
                            <span v-if="wId == 2">前锋</span>
                        </div>
                    </div>
                    <div class="cover" v-if="w.id == -1" @click="EditTeam(t,tId)"></div>
                </div>
                <!-- 编辑队伍按钮 -->
                <div class="build_team_btn" ref="build_team_btn" 
                @touchstart="$refs.build_team_btn[tId].classList.add('click')" 
                @touchend="$refs.build_team_btn[tId].classList.remove('click')"  
                @click="EditTeam(t,tId)">
                    <div class="build_team_btn_img"></div>
                    <div class="build_team_btn_font">部队{{ tId+1 }}</div>
                </div>
            </div>
        </div>

        <div class="bottom_config">
            <!-- 保存队伍数据按钮 -->
            <div class="team_config_btn" ref="save_team_data_btn"  
            @touchstart='$refs.save_team_data_btn.classList.add("click")' 
            @touchend='$refs.save_team_data_btn.classList.remove("click")'
            @click="SaveData()">
                保存
            </div>
            
            <!-- 重置配置 -->
            <div class="team_config_btn" ref="reset_config_btn"
            @touchstart='$refs.reset_config_btn.classList.add("click")'  
            @touchend='$refs.reset_config_btn.classList.remove("click")' 
            @click="ResetConfig()">
                重置
            </div>
            <!-- 添加队伍 -->
            <div class="team_config_btn" ref="add_team_btn"
            @touchstart='$refs.add_team_btn.classList.add("click")'  
            @touchend='$refs.add_team_btn.classList.remove("click")' 
            @click="AddNewTeam()">
                {{ addTeamBtnStr }}
            </div>
            <!-- 请空队伍数据按钮 -->
            <div class="team_config_btn" ref="clear_team_data_btn"  
            @touchstart='$refs.clear_team_data_btn.classList.add("click")' 
            @touchend='$refs.clear_team_data_btn.classList.remove("click")'
            @click="ClearTeam()">
                {{ clearTeamStr }}
            </div>
        </div>

        

        <TopNav title="队伍配置" />
        
        
        <!-- 路由 -->
        <router-view/>
    </div>
</template>

<script>
import WarriorElongatedCard from '@/components/style/WarriorElongatedCard.vue';
import TopNav from '@/components/container/TopNav.vue';
import Save from '../../util/save.js';
export default {
    name : 'MyTeam',
    components:{
        TopNav,
        WarriorElongatedCard
    },
    data(){
        return{
            tipStr : "",
            isAlert : false,

            addTeamBtnStr : "添加队伍",
            clearTeamStr : "清除队伍",
        }
    },
    methods:{
        //重置配置
        ResetConfig(){
            let that = this;
            let f1 = function(){
                that.$store.warriors.forEach(warrior => {
                    if(warrior.own){
                        warrior.tacticsArr.forEach((t,tId)=>{
                            if(tId > 0){
                                warrior.UnLoadTactics(tId,t)
                            }
                        })
                    }
                });
                let s = new Save(that.$store);
                s.SaveWarriorData()
                s.SaveTacticsData()
                that.$store.Alert('重置战法成功',"right");
            }
            let f2 = function(){
                that.$store.warriors.forEach(warrior => {
                    if(warrior.own && warrior.artifact){
                        warrior.UnloadArtifact()
                    }
                });
                let s = new Save(that.$store);
                s.SaveWarriorData()
                that.$store.Alert('重置宝物成功',"right");
            }
            let f3 = function(){
                that.$store.warriors.forEach(warrior => {
                    if(warrior.own){
                        warrior.tacticsArr.forEach((t,tId)=>{
                            if(tId > 0){
                                warrior.UnLoadTactics(tId,t)
                            }
                        })
                        if(warrior.artifact) warrior.UnloadArtifact()
                    }
                });
                let s = new Save(that.$store);
                s.SaveWarriorData()
                s.SaveTacticsData()
                that.$store.Alert('已重置战法和宝物',"right");
            }
            let params = {
                title:"重置",
                msg : `将所有已解锁武将进行以下配置重置...`,
                optionBtnNames : ['重置战法','重置宝物',"重置战法和宝物"],
                optionCallBack : [
                    f1,
                    f2,
                    f3
                ]
            }
            this.$store.OptionalPrompt(params)
        },
        //查看武将信息
        WarriorInfoCheck(warriorData,w_id,t_id){
            this.$store.buffer.curWarrior = warriorData;
            // this.$store.buffer.editTeamIdx = editTeamIdx;
            this.$router.push({
                path : `${this.$route.path}/warrior_info`,
            })
        },
        //编辑队伍
        EditTeam(editTeam,tId){
            // this.currentTeamIndex = index;
            this.$store.buffer.curTeam = editTeam
            this.$store.buffer.editTeamIdx = tId
            this.$router.push({
                path : `${this.$route.path}/team_info`,
            })
        },
        //添加一个新队伍
        AddNewTeam(){
            let distance = (window.innerWidth/5) + 10;
            setTimeout(()=>{
                this.$refs.team_container.scrollTo(0,distance*(this.$store.teams.list.length-5));
            },10)
            this.addTeamBtnStr = "添加中"
            this.$store.teams.ConfigEmptyTeam();
            setTimeout(() => {
                this.addTeamBtnStr = "添加队伍"
            }, 10);
        },
        //清除队伍
        ClearTeam(){
            let that = this;
            let f = function(){
                that.$store.teams.ClearTeamList();
                let save = new Save(that.$store);
                save.SaveMyTeam();
                that.$store.Alert('队伍清空成功',"right")
            }
            let params = {
                msg : `确定清除掉配将队伍列表？`,
                CallBack : f,
            }
            this.$store.Prompt(params)

            
        },
        SaveData(){
            let save = new Save(this.$store);
            save.SaveMyTeam();
            this.$store.Alert('保存成功',"right")
        }
    },
}
</script>

<style  lang="less" scoped>
.team{
    position: absolute; left: 0; top : 0;
    width : 100vw; height : 100vh;
    background: url('../../assets/background/bg\ \(1\).jpg')right bottom no-repeat;
    background-size: cover;
    .close_btn{
        position: absolute;
        background: url('../../assets/ui/ui (85).png')no-repeat;
        background-size: 100% 100%;
    }
    .texture_branch{
        left: 0; top: 15vh;
        width: 55vw;height: 12vw;
        line-height: 10vw;
        background: url('../../assets/background/bg (5).png')no-repeat;
        background-size: 100% 100%;
        font-size: 4.5vw;
        color: rgb(182, 182, 99);
        text-shadow: 0 0 0 2px black;
        text-indent: -20vw;
        transition: all .3s;
        font-family: 'FZLBJW';
    }
    //队伍总览
    .team_container{
        position: absolute; left: 50%; top : 50%;
        transform : translate(-50%,-50%);
        width: 100vw;
        height: 105vw;
        overflow-y: scroll;
        overflow-x: hidden;
        .team_box{
            position: relative;
            width: 100%;
            height: 20vw;
            background:rgba(37, 40, 43, 0.732);
            background-size: 100% 100%;
            margin: 1vw 0 0 0;
            position: relative;
            //武将的middle画像
            .team_warrior{
                float: left;
                width: 28vw;
                height: 14vw;
                // box-sizing: border-box;
                border: .3vw solid rgb(69, 68, 68);
                background: url('../../assets/background/bg\ \(21\).png')no-repeat;
                background-size: 100% 100%;
                box-shadow:  0 0 2px black;
                margin:2vw .5vw 0 2vw;
                position: relative;
                transition: all .1s;
                .position_sign{
                    position: absolute; left: 7vw; top: 14vw;
                    width: 14vw;
                    height: 3vw;
                    padding-top: 1vw;
                    text-align: center;
                    background: url('../../assets/ui/ui (133).png')no-repeat;
                    background-size: 100% 100%;
                    // color: rgb(149, 149, 149);
                    color: rgb(199, 199, 199);
                    opacity: .5;
                    text-align: center;
                    line-height: 2vw;
                    span{
                        position: absolute; left: 0; top : 0;
                        width : 100%; height : 100%;
                        font-size: 2.3vw;
                        // color: black;
                        font-family: "FZLBJW";
                    }
                }
            }
            .team_warrior:nth-of-type(1){
                margin:2vw .5vw 0 2vw;
            }
            
            
            //编辑队伍按钮
            .build_team_btn{
                position: absolute; right: .5vw; top: .5vw;
                
                width: 6vw;
                height: 19vw;
                text-align: center;
                background: url('../../assets/ui/ui (105).png')no-repeat;
                background-size: 100% 100%;
                text-align: center;
                line-height: 10vw;
                color: rgb(255, 226, 226);
                font-size: 2vw;
                opacity: .6;
                transition: all .1s;
                .build_team_btn_img{
                    position: absolute; left: .8vw; top: 2vw;
                    width: 5vw;
                    height: 5vw;
                    background: url('../../assets/ui/ui (104).png')no-repeat;
                    background-size: 100% 100%;
                }
                .build_team_btn_font{
                    position: absolute; left: 2vw; top: 8vw;
                    width: 2vw;
                    height: 6vw;
                    font-size: 2vw;
                    line-height: 3vw;
                }

            }
            .build_team_btn.click{
                opacity: 1;
                transform: scale(.9);
                
            }
        }
    }
    .team_container.longer{
        height: 126vw;
    }

    .bottom_config{
        position: absolute; bottom: 10vh; left: 0;
        width: 100vw; height: 6vw;
        .team_config_btn{
            position: relative; float: left;
            width: 20vw;  height: 6vw;
            line-height: 6vw;
            margin: 0 0 0 4vw;
            font-weight: bold;
            text-align: center;
            background: white;
            color: black;
        }
    }
}

</style>